pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz params: an array of deposit amounts and an owner address that will call withdrawAll.
    // We use a bytes calldata-style parameter by accepting a bytes to represent multiple deposits encoded as uint256[]
    function testFuzz_property(uint256[] memory deposits, address owner) public {
        // admissible domain: owner must be non-zero and the deposits array length bounded to keep fuzz wide
        vm.assume(owner != address(0));
        // keep number of deposits reasonable to avoid too large loops
        vm.assume(deposits.length <= 10);

        // Make owner be the deployed contract deployer if not the same; we will impersonate owner for withdrawAll
        // Ensure owner has enough balance to send deposits
        uint256 total = 0;
        for (uint i = 0; i < deposits.length; i++) {
            // bound each deposit to a reasonable non-negative value; allow zero deposits but at least one positive required
            deposits[i] = bound(deposits[i], 0, 1 ether);
            total += deposits[i];
        }
        // require at least one positive deposit to make distinction meaningful
        bool hasPositive = false;
        for (uint i = 0; i < deposits.length; i++) if (deposits[i] > 0) { hasPositive = true; break; }
        vm.assume(hasPositive);

        // Fund the owner so they can send deposits
        vm.deal(owner, total);

        // Send each deposit via fallback by having owner call with value
        for (uint i = 0; i < deposits.length; i++) {
            if (deposits[i] == 0) continue;
            vm.prank(owner);
            // call fallback by sending empty calldata
            (bool ok,) = address(c).call{value: deposits[i]}("0x");
            require(ok);
        }

        // Sanity: after deposits, contract balance equals sum of deposits
        // Read address(c).balance
        uint256 before = address(c).balance;
        // ensure nonzero before attempting withdrawAll
        assert(before > 0);

        // Now owner calls withdrawAll
        vm.prank(owner);
        // capture whether call reverts or not (should not revert on reference)
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // We expect the reference contract to succeed and reduce balance to zero for ANY admissible inputs.
        // The single assertion observes c: either the call reverted (ok==false) OR the post-balance must be zero.
        // For the correct contract, ok should be true and balance zero; the mutant (withdraw(0)) will leave balance>0 for some inputs
        uint256 after = address(c).balance;
        assertTrue(ok && after == 0);
    }
}

