pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an address attacker and an amount to send to the contract and forward.
    // We must ensure amount is > 0 and that attacker has funds; keep domain wide.
    function testFuzz_property(address attacker, uint256 amount) public {
        // admissible domain: attacker should be non-zero and amount bounded to reasonable range
        vm.assume(attacker != address(0));
        amount = bound(amount, 1, 1 ether);

        // Fund the contract initially from the owner (deployer) so it has balance to forward
        vm.deal(address(this), 2 ether);
        // send some ether into c so it can later be forwarded/withdrawn
        payable(address(c)).transfer(1 ether);

        // Deploy an adversarial helper that will try to withdraw from c if it can
        // This helper will, when receiving funds, attempt to call c.withdraw(address(this).balance)
        AttackerHelper helper = new AttackerHelper(address(c));
        // Ensure helper has no starting balance
        vm.deal(address(helper), 0);

        // Now call sendMoney on c to make it call the helper with some forwarded value.
        // We use the helper address as target so c will call into our helper.
        // Prepare data empty; value is amount (must be <= contract balance to avoid revert).
        uint256 forward = amount;
        // Bound forward to at most address(c).balance to avoid revert from call or running out of balance
        uint256 maxFwd = address(c).balance;
        if (maxFwd == 0) {
            // nothing to test if c has no balance; but we ensured it has 1 ether above
            assertTrue(false);
        }
        forward = bound(forward, 1, maxFwd);

        // Make the call as owner (setUp deployed c so msg.sender == owner is this test contract)
        // The helper's fallback will try to call withdraw on c. In the correct contract onlyOwner prevents it.
        // We need to call sendMoney with value=forward, so c will call helper with that value.
        // Use try/catch to avoid bubbling reverts (we still observe final balance)
        try c.sendMoney(address(helper), forward, "") {
            // call succeeded
        } catch {
            // ignore reverts; we will still check balance
        }

        // Single assertion: in the correct contract, only the owner can withdraw, so after sendMoney
        // the contract balance must be >= 0 and specifically not less than previous balance minus forwarded amount
        // because only the owner (this) could withdraw remaining funds. Here we assert that address(c).balance
        // is at least original_balance - forward. This is the invariant the mutant breaks when withdraw is
        // not restricted and the helper can drain.
        uint256 expectedMin = 1 ether - forward; // original contract balance was 1 ether
        assertTrue(address(c).balance >= expectedMin);
    }
}

// Helper that, when called (receives funds), will attempt to call withdraw on the victim contract.
contract AttackerHelper {
    address victim;
    constructor(address _v) { victim = _v; }
    fallback() external payable {
        // try to call withdraw on victim, attempting to drain it if allowed
        // use low-level call to avoid revert bubbling
        (bool s, ) = victim.call(abi.encodeWithSignature("withdraw(uint256)", address(victim).balance));
        s; // silence unused
    }
}

