pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, uint256 fundAmount) public {
        // keep domain sensible: attacker != address(0), fundAmount > 0 and not absurd
        vm.assume(attacker != address(0));
        fundAmount = bound(fundAmount, 1, 1 ether);

        // Deploy adversarial helper that will revert on fallback to simulate a failing callee
        Reverter r = new Reverter();

        // Fund the contract c so it has a balance to be potentially withdrawn
        vm.deal(address(this), fundAmount);
        // send funds into contract c from this test contract
        payable(address(c)).transfer(fundAmount);

        // Sanity: c has the funds now
        uint256 before = address(c).balance;
        // call sendMoney to route an external call to the Reverter; use owner (setUp deployer) to call
        // ensure owner (this contract) calls sendMoney; set msg.sender = address(this) already
        bytes memory empty = "";
        // sendMoney will attempt to call Reverter and that call will revert internally; sendMoney will bubble revert
        // but because sendMoney wraps the low-level call and reverts on failure, the call will actually revert.
        // To exercise both successful path and failing path, we call with target r and zero value so the call succeeds
        c.sendMoney(address(r), 0, empty);

        // After sendMoney completes, only owner is allowed to withdraw in reference contract.
        // The mutant removes onlyOwner allowing any actor to withdraw. We now simulate attacker calling withdraw.
        // Fund attacker so they can be a non-owner actor
        vm.deal(attacker, 0);
        // attacker (not owner) attempts to withdraw all funds from c
        vm.prank(attacker);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: in the reference contract, onlyOwner prevents a non-owner (attacker) from withdrawing,
        // so the non-owner call must revert (ok == false) for all inputs. The mutant removing the check will let some
        // attackers succeed (ok == true) for some inputs; thus we assert that ok == false.
        assertTrue(!ok);

        // Finally, assert the contract balance did not decrease due to the non-owner withdraw attempt
        // (This assertion reads c via address(c).balance and is implied by the non-owner withdraw failing.)
        assertTrue(address(c).balance == before);
    }
}

contract Reverter {
    fallback() external payable {
        // do nothing (succeed) for value==0; but revert for any non-zero call data? Keep it simple: always succeed
        // to ensure sendMoney can be called without reverting the whole sendMoney when value==0 above
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive the contract: send some ETH to this test, then call c.sendMoney
    // params: fundAmount - amount of ETH this test will send to c before calling sendMoney
    //         forwardValue - the _value argument passed to sendMoney
    //         target - the target address that will receive the forwarded ETH
    function check(uint fundAmount, uint forwardValue, address payable target) public payable {
        // Preconditions for meaningful test
        require(forwardValue > 0, "forwardValue must be positive");
        require(msg.value == 0, "do not send ETH to this function");

        // Fund the contract c so it has balance to forward
        // We must transfer fundAmount from this contract to c. Ensure this contract has that balance.
        require(address(this).balance >= fundAmount, "insufficient test contract balance");
        // transfer ETH into c by calling payable fallback: send via address(c).call{value: fundAmount}()
        (bool funded,) = address(c).call{value: fundAmount}("");
        require(funded, "funding c failed");

        // Record target balance before forwarding
        uint before = address(target).balance;

        // Call c.sendMoney to forward 'forwardValue' to target
        c.sendMoney(target, forwardValue, "");

        // Observe target balance after
        uint after = address(target).balance;

        // Assert: target's balance increased exactly by forwardValue.
        // Holds on original contract (which forwards the requested value) but is violated by mutant (which forwards 0).
        assert(after - before == forwardValue);
    }

    // Allow this test contract to receive ETH so it can fund c
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Receive to accept forwarded value if needed
    receive() external payable {}

    // The test: supply a target contract address that, when called with data, will cause its fallback to run
    // We cannot deploy new contracts here, so the target will be provided as an address of an existing contract
    // The behavior difference between original and mutant is whether the low-level call with data is performed
    // We drive c by calling sendMoney with a non-empty _data and a small value, then observe depositsCount
    function runTest(address payable target, uint value, bytes calldata data) public payable {
        // preconditions: this contract must hold enough balance to forward
        require(address(this).balance >= value, "insufficient balance");
